def pre_suggestion_filter_title(source):
    from suggestion_filter_icon_scope_contract import pre_suggestion_filter_icon
    source = pre_suggestion_filter_icon(source)
    for _, old, new, count in reversed(CHANGES):
        if new in source:
            assert source.count(new) == count
            source = source.replace(new, old)
    return source

def pre_suggestion_filter_title_bytes(path):
    data = path.read_bytes()
    return pre_suggestion_filter_title(data.decode()).encode() if path.suffix == '.swift' else data

